def get_operation():
    """Get user input for the mathematical operation."""
    while True:
        operation = input("Enter the mathematical operation (+, -, *, /): ").strip()
        if operation in ['+', '-', '*', '/']:
            return operation
        else:
            print("Invalid operation. Please try again.")

def get_numbers():
    """Get user input for two numbers."""
    while True:
        try:
            num1 = float(input("Enter the first number: "))
            num2 = float(input("Enter the second number: "))
            return num1, num2
        except ValueError:
            print("Invalid input. Please enter numbers only.")

def perform_operation(operation, num1, num2):
    """Perform the given mathematical operation on the two numbers."""
    if operation == '+':
        result = num1 + num2
    elif operation == '-':
        result = num1 - num2
    elif operation == '*':
        result = num1 * num2
    elif operation == '/':
        if num2 == 0:
            raise ValueError("Cannot divide by zero.")
        result = num1 / num2
    else:
        raise ValueError("Invalid operation.")
    return result

while True:
    operation = get_operation()
    if operation == 'quit':
        break
    num1, num2 = get_numbers()
    try:
        result = perform_operation(operation, num1, num2)
        print(f"{num1} {operation} {num2} = {result}")
    except ValueError as e:
        print(e)
```
